def hint(secret, guess):
    if guess < secret:
        return "higher"
    if guess > secret:
        return "lower"
    return "correct"


def read_guess(text):
    s = text.strip()
    if not s.isdigit():
        return None
    n = int(s)
    if 1 <= n <= 100:
        return n
    return None


def play(secret):
    used = 0
    while used < 5:
        guess = read_guess(input())
        if guess is None:
            print("Please type a whole number from 1 to 100.")
            continue
        used += 1
        result = hint(secret, guess)
        if result == "correct":
            print(f"Correct! Guesses used: {used}")
            return
        print(result)
    print(f"Out of guesses. It was {secret}.")


if __name__ == "__main__":
    play(int(input()))

